{
  "rules": [
    {
      "id": "P1-L1",
      "quote": "Implement a small reconciliation tool for an e-commerce settlement team."
    },
    {
      "id": "P1-L2",
      "quote": "Each day, the team exports one mixed text file containing both order and payment records."
    },
    {
      "id": "P1-L3",
      "quote": "The tool parses the file, matches payments to orders, and produces a summary."
    },
    {
      "id": "P1-L4",
      "quote": "The following conventions apply everywhere: - Store and calculate every monetary amount internally as an integer number of cents."
    },
    {
      "id": "P1-L6",
      "quote": "- Silently skip records that cannot be parsed or do not satisfy the format."
    },
    {
      "id": "P1-L8",
      "quote": "- Process only records whose currency is exactly `USD` after surrounding whitespace is removed."
    },
    {
      "id": "P1-L13",
      "quote": "Every line has exactly six fields separated by `|`: ```text TYPE|RECORD_ID|ORDER_ID|AMOUNT|CURRENCY|TIMESTAMP ``` - `TYPE` is `ORDER` or `PAYMENT`, matched without regard to case and normalised to uppercase."
    },
    {
      "id": "P1-L29",
      "quote": "fields are read by those key names, for example `record[\"type\"]`."
    },
    {
      "id": "P1-L49",
      "quote": "- `parse_amount(s)` returns integer cents for a valid amount string and `None` otherwise."
    },
    {
      "id": "P1-L52",
      "quote": "- `parse_record(line)` returns the exact parsed-record dictionary described in Part 2, or `None` when any field is invalid."
    },
    {
      "id": "P1-L53",
      "quote": "- `load_records(text)` parses all lines, silently skips invalid lines, and applies the first-valid-record duplicate rule."
    }
  ],
  "checks": [
    {
      "assertion": "assert parse_amount('12.30') == 1230",
      "result": "OBSERVED_FAIL",
      "ttl": 1
    },
