"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        amount = Decimal(s)
        if amount != amount.to_integral_value(rounding=ROUND_HALF_UP):
            return None
        if amount < 0 or amount.as_tuple().exponent < -2:
            return None
        return int(amount * 100)
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None:
        return None
    if currency != 'USD':
        return None
    try:
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    except ValueError:
        return None
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    matched_results = []
    order_dict = {record['order_id']: record for record in records if record['type'] == 'ORDER'}
    payment_dict = {record['order_id']: [] for record in records if record['type'] == 'PAYMENT'}

    for record in records:
        if record['type'] == 'PAYMENT':
            payment_dict[record['order_id']].append(record)

    for order_id, order in order_dict.items():
        matched = False
        for payment in payment_dict[order_id]:
            if payment['amount'] >= 0 and order['timestamp'] <= payment['timestamp'] <= order['timestamp'] + timedelta(hours=72):
                matched_results.append({
                    'order_id': order_id,
                    'status': 'matched',
                    'amount': payment['amount']
                })
                matched = True
                break
        if not matched:
            matched_results.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matched_results


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(matches)
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(match['order_id'] for match in matches if match['status'] == 'unmatched')

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

