"""Blank starter for the reconciliation task."""

from datetime import datetime, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP


def parse_amount(s):
    if not isinstance(s, str):
        return None
    try:
        d = Decimal(s)
        if d < 0 or len(str(d).split('.')[-1]) > 3:
            return None
        cents = int(d * 100)
        if d != d.to_integral_value():
            return None
        return cents
    except (InvalidOperation, ValueError):
        return None


def parse_record(line):
    fields = line.strip().split('|')
    if len(fields) != 6:
        return None
    record_type, record_id, order_id, amount, currency, timestamp = map(str.strip, fields)
    if record_type.upper() not in ['ORDER', 'PAYMENT']:
        return None
    if record_type.upper() == 'ORDER' and record_id != order_id:
        return None
    amount_cents = parse_amount(amount)
    if amount_cents is None or currency != 'USD':
        return None
    timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M')
    return {
        'type': record_type.upper(),
        'record_id': record_id,
        'order_id': order_id,
        'amount': amount_cents,
        'currency': currency,
        'timestamp': timestamp
    }


def load_records(text):
    records = []
    seen_ids = set()
    for line in text.strip().splitlines():
        record = parse_record(line)
        if record and record['record_id'] not in seen_ids:
            records.append(record)
            seen_ids.add(record['record_id'])
    return records


def match_payments(records):
    matched = []
    unmatched_ids = set()
    order_timestamps = {record['order_id']: record['timestamp'] for record in records if record['type'] == 'ORDER'}

    for record in records:
        if record['type'] == 'PAYMENT':
            order_id = record['order_id']
            if order_id in order_timestamps:
                order_timestamp = order_timestamps[order_id]
                if record['amount'] >= 0 and order_timestamp <= record['timestamp'] <= order_timestamp + timedelta(hours=72):
                    matched.append({
                        'order_id': order_id,
                        'status': 'matched',
                        'amount': record['amount']
                    })
                    continue

        unmatched_ids.add(record['order_id'])

    for order_id in order_timestamps:
        if order_id not in unmatched_ids:
            matched.append({
                'order_id': order_id,
                'status': 'unmatched',
                'amount': 0
            })

    return matched


def compute_refunds(records):
    return sum(-record['amount'] for record in records if record['type'] == 'PAYMENT' and record['amount'] < 0)


def build_summary(matches, refund_total):
    total_orders = len(set(match['order_id'] for match in matches))
    matched_count = sum(1 for match in matches if match['status'] == 'matched')
    net_total = sum(match['amount'] for match in matches if match['status'] == 'matched') - refund_total
    unmatched_ids = sorted(set(match['order_id'] for match in matches if match['status'] == 'unmatched'))

    return {
        'total_orders': total_orders,
        'matched_count': matched_count,
        'net_total': net_total,
        'unmatched_ids': unmatched_ids
    }

